if [ "$before_sites" = "$after_sites" ] && [ "$before_users" = "$after_users" ] && [ "$before_sm" = "$after_sm" ] && [ "$before_am" = "$after_am" ] && [ "$typed" = "$after_sites" ] && [ "$ok035" = "t" ] && [ "$ok038" = "t" ] && [ "$ok039" = "t" ] && [ "$ok040" = "t" ] && [ "$ok041" = "t" ] && [ "$ok044" = "t" ] && [ "$ok047" = "t" ] && [ "$ok051" = "t" ] && [ "$idem" = "t" ]; then
